        .Where(message => message.SentAtUtc == null)
        .OrderBy(message => message.CreatedAtUtc)
        .Take(50)
        .ToListAsync(ct);

    foreach (var message in pending)
    {
        await bus.PublishAsync(message.Type, message.Payload, ct);
        message.SentAtUtc = clock.UtcNow;
    }

