public sealed class Order : AggregateRoot
{
    private readonly List<OrderLine> _lines = [];
    public IReadOnlyList<OrderLine> Lines => _lines;
    public OrderStatus Status { get; private set; }
    public Money Total { get; private set; }

    private Order() { }

    public static Order Place(CustomerId customerId, IEnumerable<OrderLine> lines)
    {
        var order = new Order
        {
            Status = OrderStatus.Pending,
            Total = Money.Zero
        };
        foreach (var line in lines)
            order.AddLine(line);

        order.Raise(new OrderPlaced(order.Id, customerId));
        return order;
    }

    public void AddLine(OrderLine line)
    {
        if (Status != OrderStatus.Pending)
            throw new DomainException("Cannot modify a non-pending order.");

        _lines.Add(line);
        Total = Total.Add(line.Subtotal);
    }
}

public sealed record Money(decimal Amount, string Currency)
{
    public static readonly Money Zero = new(0, "GBP");
    public Money Add(Money other) =>
        Currency == other.Currency
            ? this with { Amount = Amount + other.Amount }
            : throw new DomainException("Currency mismatch.");
}

