public class OrderType : ObjectType<Order>
{
    protected override void Configure(IObjectTypeDescriptor<Order> descriptor)
    {
        descriptor.Field(o => o.Id);
        descriptor.Field(o => o.Total);
        descriptor.Field("customer")
            .ResolveWith<Resolvers>(r => r.GetCustomerAsync(default!, default!, default!))
            .UseDataLoader<CustomerByIdDataLoader>();
    }

    private sealed class Resolvers
    {
        public Task<Customer> GetCustomerAsync(
            [Parent] Order order, CustomerByIdDataLoader loader, CancellationToken ct) =>
            loader.LoadAsync(order.CustomerId, ct);
    }
}

