public interface IOrderGrain : IGrainWithGuidKey
{
    Task<OrderStatus> GetStatusAsync();
    Task PlaceAsync(IReadOnlyList<OrderLine> lines);
}

public sealed class OrderGrain(
    [PersistentState("order")] IPersistentState<OrderState> state)
    : Grain, IOrderGrain
{
    public Task<OrderStatus> GetStatusAsync() => Task.FromResult(state.State.Status);

    public async Task PlaceAsync(IReadOnlyList<OrderLine> lines)
    {
        state.State = state.State with { Lines = lines, Status = OrderStatus.Placed };
        await state.WriteStateAsync();
    }
}
